idence":"high","completeness_pct":91,"quality_passed":1,"human_review_required":0,"unsourced_fields":["audited_revenue","audited_player_liabilities","unique_active_players","cold_wallet_reserve_coverage","jurisdiction_by_jurisdiction_availability"],"last_reviewed":"2026-07-29","updated_at":"2026-07-29"},"sources":[{"source_id":"casino:source:cloudbet:about-2026","canonical_url":"https://www.cloudbet.com/en/about-us","title":"About Cloudbet","publisher":"Cloudbet","accessed_at":"2026-07-29","source_tier":"B","source_role":"primary","resolving":1,"evidence_reviewed":1,"evidence_reviewed_at":"2026-07-29","evidence_reviewer":"chaindump-research-desk","notes":"Current operator-controlled product and history disclosure; not an independent audit of usage, custody or financial performance."},{"source_id":"casino:source:cloudbet:licence-2025","canonical_url":"https://www.cloudbet.com/en/support/articles/107963-what-gambling-licenses-does-cloudbet-have","title":"What gambling licenses does Cloudbet have?","publisher":"Cloudbet Help Center","published_at":"2025-06-17","accessed_at":"2026-07-29","source_tier":"B","source_role":"primary","resolving":1,"evidence_reviewed":1,"evidence_reviewed_at":"2026-07-29","evidence_reviewer":"chaindump-research-desk","notes":"Operator licensing statement; recorded as an entity-and-domain-specific observation, not a global legality conclusion."}],"claims":[{"claim_id":"casino:claim:cloudbet:identity-current","case_id":"cloudbet-dot-com","field_path":"identity.operator_domain_product","source_id":"casino:source:cloudbet:about-2026","evidence_locator":"Current about page describes a sportsbook, casino, live casino and esports product and its footer identifies Halcyon Super Holdings B.V. as operator of cloudbet.com.","claim_type":"identity","support_direction":"supports","analyst_note":"The payment subsidiary named in the footer is not treated as the gambling operator.","checked_at":"2026-07-29"},{"claim_id":"casino:claim:cloudbet:launch-longevity","case_id":"cloudbet-dot-com","field_path":"launched,status.active","source_id":"casino:source:cloudbet:about-2026","evidence_locator":"Page states Cloudbet was founded in 2013, remains a current product, supports more than 30 cryptocurrencies and provides thousands of casino games.","claim_type":"status","support_direction":"supports","analyst_note":"Operator-reported longevity and breadth support operational success, not audited profitability.","checked_at":"2026-07-29"},{"claim_id":"casino:claim:cloudbet:licence","case_id":"cloudbet-dot-com","field_path":"licence.curacao","source_id":"casino:source:cloudbet:licence-2025","evidence_locator":"Help article identifies Curaçao Gaming Authority licence OGL/2024/328/0599 issued to Halcyon Super Holdings B.V., company number 148526.","claim_type":"licence","support_direction":"supports","analyst_note":"No inference is made about availability outside the licensed entity/domain/activity scope.","checked_at":"2026-07-29"}],"licences":[{"licence_observation_id":"casino:licence:cloudbet:curacao","case_id":"cloudbet-dot-com","authority":"Curaçao Gaming Authority","licence_id":"OGL/2024/328/0599","legal_entity":"Halcyon Super Holdings B.V.","domains":["cloudbet.com"],"activities":["sportsbook","casino"],"jurisdiction":"Curaçao","licence_status":"active","valid_from":null,"valid_until":null,"as_of":"2026-07-29","source_claim_ids":["casino:claim:cloudbet:licence"],"notes":"Status is based on the current operator-controlled help and footer surface; dates and regulator-register reconciliation remain unverified."}],"observations":[],"events":[{"event_id":"casino:event:cloudbet:launch:2013","case_id":"cloudbet-dot-com","event_type":"launch","event_date":"2013","date_precision":"year","amount_usd":null,"description":"Cloudbet says the crypto sportsbook and casino was founded in 2013.","source_claim_ids":["casino:claim:cloudbet:launch-longevity"]}],"forensic_analysis":{"version":"forensic-analysis-v1","outcome":{"label":"successful","summary":"Cloudbet is an operationally successful crypto-gambling incumbent within the narrow cloudbet.com scope: the current service traces its launch to 2013, spans sportsbook and casino products, and identifies a current operator and Curaçao licence. This does not establish audited profitability, solvency or universal legal availability.","confidence":"high","as_of":"2026-07-29","source_refs":["https://www.cloudbet.com/en/about-us","https://www.cloudbet.com/en/support/articles/107963-what-gambling-licenses-does-cloudbet-have"]},"why":{"summary":"More than a decade of continuity, expansion from Bitcoin into multiple assets, and a combined sportsbook/casino account plausibly created retention and cross-sell advantages. The reviewed evidence is operator-controlled, so it cannot isolate causality or verify financial quality.","confidence":"medium","source_refs":["https://www.cloudbet.com/en/about-us"]},"strategic_choices":[{"decision":"Retain a crypto-first custodial product while expanding beyond Bitcoin to more than 30 supported cryptocurrencies.","consequence":"The product broadened funding access without abandoning its crypto-native positioning, while preserving operator custody and counterparty risk.","confidence":"high","source_refs":["https://www.cloudbet.com/en/about-us"]},{"decision":"Combine sportsbook, casino, live casino and esports inside one account and wallet.","consequence":"A broader lobby can cross-sell users and diversify product demand, although no reviewed source measures incremental retention or revenue.","confidence":"medium","source_refs":["https://www.cloudbet.com/en/about-us"]},{"decision":"Operate cloudbet.com through a named Curaçao company and licence.","consequence":"The disclosure makes the current entity and licence traceable, but does not authorize every activity in every user jurisdiction.","confidence":"high","source_refs":["https://www.cloudbet.com/en/support/articles/107963-what-gambling-licenses-does-cloudbet-have"]}],"counterfactual":{"summary":"A Bitcoin-only single-product strategy likely would have narrowed Cloudbet''s addressable market and cross-sell options; moving fully onchain would have reduced some custody dependence but required a materially different product and compliance model. Neither effect is measured.","confidence":"medium","source_refs":["https://www.cloudbet.com/en/about-us"]},"watch":[{"signal":"Operator, company-number, domain or Curaçao licence changes.","implication":"Any mismatch could materially change the legal-entity and regulatory assessment.","source_refs":["https://www.cloudbet.com/en/support/articles/107963-what-gambling-licenses-does-cloudbet-have"]},{"signal":"Current supported-asset and product breadth plus independently measured player activity.","implication":"Sustained breadth and third-party activity would strengthen the longevity thesis; contraction would weaken it.","source_refs":["https://www.cloudbet.com/en/about-us"]}],"unknowns":["What are audited player liabilities, reserves, revenue and profit?","How many unique active users and repeat depositors does the product retain?","Which countries and activities are legally available under each local regime?"],"review":{"status":"current","last_reviewed_at":"2026-07-29","next_review_at":"2026-08-05","reviewer":"chaindump-research-desk"}},"synthesis":{"present_situation":"Cloudbet remains an active custodial crypto sportsbook and casino under a disclosed Curaçao operator and licence.","business_mechanism":"A single custodial wallet supports sportsbook, casino, live-casino and esports wagering across crypto and fiat funding rails.","token_contribution":"No native platform token was identified; supported cryptocurrencies function as deposits, balances and withdrawals.","chain_dependence":"Blockchains are payment rails. Wagers, balances and settlement remain operator-controlled rather than executed as public onchain games.","risk_legal_posture":"The named entity and licence improve traceability, but audited custody, liabilities and jurisdiction-specific legality remain outside the reviewed evidence.","success_failure_hypotheses":"Longevity, crypto-native funding breadth and cross-product access plausibly support durable operation.","counterfactual":"Remaining Bitcoin-only or single-product likely would have constrained growth; the size of the effect is unknown.","outlook":{"as_of":"2026-07-29","product_status":"active","licence_status":"operator reports active","scope_guard":"Operational success only; no audited-solvency or universal-legality claim."},"lessons_learned":["Long operating history is meaningful product evidence but not an audit.","Crypto payment support does not make a custodial casino an onchain protocol."],"source_claim_ids":["casino:claim:cloudbet:identity-current","casino:claim:cloudbet:launch-longevity","casino:claim:cloudbet:licence"],"analyst_id":"chaindump-research-desk","reviewed_at":"2026-07-29"}},{"case":{"case_id":"shuffle-dot-com","brand_name":"Shuffle","entity_kind":"custodial_operator","product_subtype":"casino_and_sportsbook","legal_operator":"Natural Nine B.V.","parent_entity":null,"primary_domain":"shuffle.com","launched":null,"date_precision":"unknown","custody_model":"custodial","chains":["Ethereum"],"product_scope_note":"This case covers the custodial casino, sportsbook, SHFL wagering, lottery and token program at shuffle.com operated by Natural Nine B.V. Ethereum scope refers to the SHFL ERC-20 and onchain burns, not public-chain execution of every wager. It excludes unrelated projects or tokens named Shuffle.","status":"active","status_as_of":"2026-07-29","outcome_label":"successful","outcome_as_of":"2026-07-29","outcome_rule_id":"casino-wave6-current-token-product-economics-v1","token_status":"documented","token_symbol":"SHFL","token_name":"Shuffle","token_contracts":[{"chain":"Ethereum","address":"0x8881562783028F5c1BCB985d2283D5E170D88888","contract_role":"ERC-20 utility token"}],"token_launch_date":null,"token_utility":"SHFL can be wagered, staked for lottery entry and used in airdrop and VIP programs.","token_fee_revenue_rights":"Shuffle reports that 30% of SHFL-denominated net gaming revenue funds weekly burns and, after the lottery launch, 15% of platform net gaming revenue funds the lottery prize pool. SHFL confers no equity, governance, voting or securities rights.","token_supply":{"max_supply":1000000000,"total_supply_as_of_2026_06_26":923295560,"cumulative_burned_as_of_2026_06_26":76704440,"unit":"SHFL"},"cohort_id":"web3-casino-wave6-2026-07-29","cohort_role":"case","selection_rule_id":"casino-wave6-product-model-contrast-v1","selection_as_of":"2026-07-29","confidence":"high","completeness_pct":94,"quality_passed":1,"human_review_required":0,"unsourced_fields":["audited_revenue","audited_player_liabilities","unique_active_players","token_launch_date","independent_verification_of_NGR_inputs"],"last_reviewed":"2026-07-29","updated_at":"2026-07-29"},"sources":[{"source_id":"casino:source:shuffle:q2-2026","canonical_url":"https://shuffle.com/blog/shfl-lottery-token-update-q2-2026","title":"SHFL Lottery & Token Update – Q2 2026","publisher":"Shuffle","published_at":"2026-06","accessed_at":"2026-07-29","source_tier":"B","source_role":"primary","resolving":1,"evidence_reviewed":1,"evidence_reviewed_at":"2026-07-29","evidence_reviewer":"chaindump-research-desk","notes":"Detailed operator report with onchain links; NGR inputs and activity figures are not independently audited in this dossier."},{"source_id":"casino:source:shuffle:token-dashboard-2026","canonical_url":"https://shuffle.com/token","title":"SHFL Token Dashboard","publisher":"Shuffle","accessed_at":"2026-07-29","source_tier":"B","source_role":"primary","resolving":1,"evidence_reviewed":1,"evidence_reviewed_at":"2026-07-29","evidence_reviewer":"chaindump-research-desk","notes":"Current product and footer source for operator and licensing identity; dynamic dashboard values are not used where they failed to render."}],"claims":[{