promise of holder return and NGR is operator-defined.","checked_at":"2026-07-29"}],"licences":[{"licence_observation_id":"casino:licence:shuffle:curacao","case_id":"shuffle-dot-com","authority":"Curaçao Gaming Control Board","licence_id":"OGL/2024/1337/0628","legal_entity":"Natural Nine B.V.","domains":["shuffle.com"],"activities":["games of chance","casino","sportsbook"],"jurisdiction":"Curaçao","licence_status":"active","valid_from":null,"valid_until":null,"as_of":"2026-07-29","source_claim_ids":["casino:claim:shuffle:operator-licence"],"notes":"Current website disclosure; no conclusion about availability in restricted user jurisdictions."}],"observations":[{"observation_id":"casino:observation:shuffle:burned:2026-06-26","case_id":"shuffle-dot-com","metric_dimension":"cumulative_token_burn","value":76704440,"unit":"token","currency":"SHFL","window_start":null,"window_end":"2026-06-26","window_definition":"Operator-reported cumulative burn through the stated snapshot date.","as_of":"2026-06-26","product_scope":"SHFL Ethereum token","chain_scope":["Ethereum"],"method":"Transcribed from the dated Q2 2026 token update.","formula":"reported cumulative burned SHFL","raw_input_ids":[],"source_claim_ids":["casino:claim:shuffle:token-supply"],"quality_flags":["operator_reported","onchain_links_available","not_revenue"]},{"observation_id":"casino:observation:shuffle:lottery-stake:2026-06-26","case_id":"shuffle-dot-com","metric_dimension":"lottery_token_staked","value":288212900,"unit":"token","currency":"SHFL","window_start":null,"window_end":"2026-06-26","window_definition":"Point-in-time SHFL staked for lottery entry.","as_of":"2026-06-26","product_scope":"SHFL Lottery","chain_scope":["Ethereum"],"method":"Transcribed from the dated Q2 2026 token update.","formula":"reported staked SHFL","raw_input_ids":[],"source_claim_ids":["casino:claim:shuffle:lottery-activity"],"quality_flags":["operator_reported","not_unique_players","not_revenue"]}],"events":[{"event_id":"casino:event:shuffle:airdrop3:2026-03-07","case_id":"shuffle-dot-com","event_type":"token_launch","event_date":"2026-03-07","date_precision":"day","amount_usd":null,"description":"SHFL Airdrop 3 began, scheduling 90 million SHFL over 52 weeks; this is an airdrop-program launch, not the original token launch.","source_claim_ids":["casino:claim:shuffle:lottery-activity"]}],"forensic_analysis":{"version":"forensic-analysis-v1","outcome":{"label":"successful","summary":"Shuffle has a current casino/sportsbook product and a functioning token loop with dated Q2 2026 burns, lottery staking, NGR routing and weekly activity. The success label is operational and mechanism-based; figures remain operator-reported and do not establish audited financial success.","confidence":"high","as_of":"2026-07-29","source_refs":["https://shuffle.com/blog/shfl-lottery-token-update-q2-2026","https://shuffle.com/token"]},"why":{"summary":"SHFL is integrated into wagering, lottery entry, airdrops, VIP benefits and supply burns rather than existing only as a tradable badge. Dated staking and draw data show use of the loop, while the operator''s control over NGR reporting, treasury allocation and program rules limits causal certainty.","confidence":"high","source_refs":["https://shuffle.com/blog/shfl-lottery-token-update-q2-2026"]},"strategic_choices":[{"decision":"Make SHFL a wager asset and entry asset for a recurring USDC lottery.","consequence":"The token gains repeat product utility and lockup demand, but users remain exposed to wagering risk and operator-defined eligibility.","confidence":"high","source_refs":["https://shuffle.com/blog/shfl-lottery-token-update-q2-2026"]},{"decision":"Route stated portions of NGR to token burns and the lottery prize pool.","consequence":"Platform activity is connected to token supply and player rewards without giving holders equity, governance or guaranteed returns.","confidence":"high","source_refs":["https://shuffle.com/blog/shfl-lottery-token-update-q2-2026"]},{"